var VERSES = {"month": 3, "monthName": "هاتور", "source": "نص فاندايك بالتشكيل من bible.com (AVD/SVD)، اتنقل حرف حرف", "scriptureReviewed": true, "days": {"6": {"ref": "لو ٨: ١٥", "usfm": "LUK.8.15", "from": "LG", "text": "وَالَّذِي فِي الأَرْضِ الْجَيِّدَةِ، هُوَ الَّذِينَ يَسْمَعُونَ الْكَلِمَةَ فَيَحْفَظُونَهَا فِي قَلْبٍ جَيِّدٍ صَالِحٍ، وَيُثْمِرُونَ بِالصَّبْرِ.", "title": "مثل الزارع", "reflection": "الزارع رمى نفس البذرة في ٤ أراضي: طريق، وصخر، وشوك، وأرض جيدة. البذرة ماتغيرتش. اللي اتغيّر هو الأرض اللي وقعت فيها. والأرض الجيدة بتعمل ٣ حاجات:", "question": "قلبي النهارده شبه أنهي أرض من الأربعة؟", "reflectionReviewed": true}, "1": {"ref": "يو ١٠: ١١", "usfm": "JHN.10.11", "from": "LG", "text": "أَنَا هُوَ الرَّاعِي الصَّالِحُ، وَالرَّاعِي الصَّالِحُ يَبْذِلُ نَفْسَهُ عَنِ الْخِرَافِ.", "title": "الراعي الصالح", "reflection": "الأجير بيحرس الخرفان طول ما الدنيا أمان، ولما الديب ييجي بيهرب. المسيح قال إنه مش أجير: هو الراعي اللي عنده استعداد يبذل حياته عشان خرافه، وده اللي عمله فعلًا على الصليب. يعني إنت مش رقم في القطيع. انت انسان محبوب اتدفع تمنه.", "question": "فيه حاجة شايلها لوحدك النهارده محتاج تسلّمها للراعي؟", "reflectionReviewed": true}, "2": {"ref": "مت ١٦: ١٦", "usfm": "MAT.16.16", "from": "LG", "text": "فَأَجَابَ سِمْعَانُ بُطْرُسُ وَقَالَ: «أَنْتَ هُوَ الْمَسِيحُ ابْنُ اللهِ الْحَيِّ!».", "title": "إنت مين بالنسبة لي؟", "reflection": "يسوع سأل تلاميذه سؤالين: الناس بتقول عني إيه؟ وإنتو بتقولوا انا مين؟ السؤال الأول سهل، بنحكي فيه كلام غيرنا. التاني محدش يقدر يجاوب عليه بدالك. بطرس جاوب من قلبه، والمسيح قاله إن ده إعلان من الآب.", "question": "لو المسيح سألك النهارده «إنت بتقول انا مين؟»، هتقوله إيه بكلامك انت؟", "reflectionReviewed": true}, "3": {"ref": "رو ٥: ٥", "usfm": "ROM.5.5", "from": "PA", "text": "وَالرَّجَاءُ لَا يُخْزِي، لِأَنَّ مَحَبَّةَ اللهِ قَدِ انْسَكَبَتْ فِي قُلُوبِنَا بِالرُّوحِ الْقُدُسِ الْمُعْطَى لَنَا.", "title": "رجاء ما بيكسفش", "reflection": "فيه حاجات بنستناها وتخذلنا: نتيجة، أو وعد من حد، أو فرصة. بولس بيقول إن الرجاء في ربنا مختلف، ما بيكسفناش، لأن أساسه مش ظروفنا. أساسه محبة ربنا اللي الروح القدس سكبها في قلوبنا.", "question": "إيه الحاجة اللي مستنيها ومحتاج تحط رجاءك فيها في ربنا مش في الظروف؟", "reflectionReviewed": true}, "4": {"ref": "يو ١٦: ٢٢", "usfm": "JHN.16.22", "from": "LG", "text": "فَأَنْتُمْ كَذَلِكَ، عِنْدَكُمُ الْآنَ حُزْنٌ. وَلَكِنِّي سَأَرَاكُمْ أَيْضًا فَتَفْرَحُ قُلُوبُكُمْ، وَلَا يَنْزِعُ أَحَدٌ فَرَحَكُمْ مِنْكُمْ.", "title": "فرح محدش ياخده", "reflection": "المسيح قال الكلام ده لتلاميذه وهو عارف إنهم داخلين على أيام حزن. ما قالهمش إن الحزن مش هييجي. قالهم إن بعده فرح، وإن الفرح ده محدش يقدر ياخده منهم، لأن مصدره هو ربنا نفسه، مش الظروف.", "question": "إيه اللي مزعّلك الأيام دي؟ تقدر تقول لربنا عليه بصراحة؟", "reflectionReviewed": true}, "5": {"ref": "مر ١٠: ٤٥", "usfm": "MRK.10.45", "from": "LG", "text": "لِأَنَّ ابْنَ الْإِنْسَانِ أَيْضًا لَمْ يَأْتِ لِيُخْدَمَ بَلْ لِيَخْدِمَ وَلِيَبْذِلَ نَفْسَهُ فِدْيَةً عَنْ كَثِيرِينَ.", "title": "جه يخدم", "reflection": "يعقوب ويوحنا طلبوا الكراسي اللي جنب المسيح في مجده. وهو ردّ عليهم إن العظمة عنده إنك تخدم، مش إنك تتخدم. وهو نفسه جه عشان يخدم ويبذل حياته علشان خاطرنا.", "question": "مين حواليك تقدر تخدمه النهارده من غير ما حد يشوف؟", "reflectionReviewed": true}, "7": {"ref": "رو ٨: ٢٨", "usfm": "ROM.8.28", "from": "PA", "text": "وَنَحْنُ نَعْلَمُ أَنَّ كُلَّ الْأَشْيَاءِ تَعْمَلُ مَعًا لِلْخَيْرِ لِلَّذِينَ يُحِبُّونَ اللهَ، الَّذِينَ هُمْ مَدْعُوُّونَ حَسَبَ قَصْدِهِ.", "title": "كل الأشياء", "reflection": "الآية دي مش بتقول إن كل حاجة بتحصل حلوة. بتقول إن ربنا بيشغّل كل الأشياء مع بعض للخير، للي بيحبوه. حتى الحاجات اللي مش فاهمينها النهارده داخلة في قصة أكبر هو كاتبها.", "question": "فيه موقف صعب عدّى عليك وشفت بعده إن ربنا عمل منه خير؟", "reflectionReviewed": true}, "8": {"ref": "يو ١: ٤٦", "usfm": "JHN.1.46", "from": "LG", "text": "فَقَالَ لَهُ نَثَنَائِيلُ: «أَمِنَ النَّاصِرَةِ يُمْكِنُ أَنْ يَكُونَ شَيْءٌ صَالِحٌ؟». قَالَ لَهُ فِيلُبُّسُ: «تَعَالَ وَانْظُرْ».", "title": "تعال وشوف", "reflection": "نثنائيل كان شاكك: هو ممكن ييجي حاجة كويسة من الناصرة؟ فيلبس ما دخلش معاه في جدال. قاله جملة واحدة: تعال وشوف بنفسك. ولما جه وقابل المسيح، اتغيّر.", "question": "مين صاحبك اللي ممكن تقوله «تعال وشوف» بدل ما تجادله؟", "reflectionReviewed": true}, "9": {"ref": "لو ٦: ٢١", "usfm": "LUK.6.21", "from": "MG", "text": "طُوبَاكُمْ أَيُّهَا الْجِيَاعُ الْآنَ، لِأَنَّكُمْ تُشْبَعُونَ. طُوبَاكُمْ أَيُّهَا الْبَاكُونَ الْآنَ، لِأَنَّكُمْ سَتَضْحَكُونَ.", "title": "طوباكم", "reflection": "المسيح بيقول طوبى للجعانين وللي بيبكوا دلوقتي. مش لأن الجوع والبكا حلوين، لكن لأن ربنا شايفهم ووعدهم إن ده مش آخر الحكاية: هيشبعوا وهيضحكوا.", "question": "إيه اللي ناقصك أو وجعك النهارده؟ قدّمه لربنا وصدّق إنه شايفه.", "reflectionReviewed": true}, "10": {"ref": "أف ٥: ٨", "usfm": "EPH.5.8", "from": "PA", "text": "لِأَنَّكُمْ كُنْتُمْ قَبْلًا ظُلْمَةً، وَأَمَّا الْآنَ فَنُورٌ فِي الرَّبِّ. اسْلُكُوا كَأَوْلَادِ نُورٍ.", "title": "ولاد نور", "reflection": "بولس بيقول إحنا كنا ظلمة، ودلوقتي بقينا نور في الرب. مش بس بنشوف النور، إحنا بقينا نور. والمطلوب إننا نمشي بالشكل ده، فكلامنا وتصرفاتنا تنوّر للي حوالينا.", "question": "فين اللي مكان والوقت اللي محتاج تبقى نور فيه؟", "reflectionReviewed": true}, "11": {"ref": "رو ٨: ١٨", "usfm": "ROM.8.18", "from": "PA", "text": "فَإِنِّي أَحْسِبُ أَنَّ آلَامَ الزَّمَانِ الْحَاضِرِ لَا تُقَاسُ بِالْمَجْدِ الْعَتِيدِ أَنْ يُسْتَعْلَنَ فِينَا.", "title": "ما تتقارنش", "reflection": "بولس عاش آلام كتير: اتضرب واتسجن وغرق. ومع كده بيقول إن آلام الوقت ده ما تتقارنش بالمجد اللي ربنا محضّره. مش بيقلّل من الألم، بس بيحطّه في حجمه الحقيقي قدام الأبدية.", "question": "إيه الحاجة اللي مكبّرها جواك ومحتاج تشوف حجمها الحقيقي قدام ربنا؟", "reflectionReviewed": true}, "12": {"ref": "عب ١: ١٤", "usfm": "HEB.1.14", "from": "PA", "text": "أَلَيْسَ جَمِيعُهُمْ أَرْوَاحًا خَادِمَةً مُرْسَلَةً لِلْخِدْمَةِ لِأَجْلِ الْعَتِيدِينَ أَنْ يَرِثُوا الْخَلَاصَ!", "title": "أرواح خادمة", "reflection": "النهارده عيد رئيس الملائكة ميخائيل. والآية بتقول إن الملائكة أرواح ربنا بيبعتها عشان تخدم اللي هيرثوا الخلاص. يعني إنت مش لوحدك: ربنا بيبعت ملايكته يحرسوك.", "question": "إمتى آخر مرة حسيت إن ربنا حماك من حاجة؟ اشكره عليها النهارده.", "reflectionReviewed": true}, "13": {"ref": "يه ١: ٢١", "usfm": "JUD.1.21", "from": "CA", "text": "وَاحْفَظُوا أَنْفُسَكُمْ فِي مَحَبَّةِ اللهِ، مُنْتَظِرِينَ رَحْمَةَ رَبِّنَا يَسُوعَ الْمَسِيحِ لِلْحَيَاةِ الْأَبَدِيَّةِ.", "title": "احفظوا نفسكم", "reflection": "يهوذا بيكتب لناس عايشين وسط تعاليم غلط وضغوط كتير. وصيته بسيطة: احفظوا نفسكم في محبة ربنا. زي ما بتحافظ على نفسك في مكان دافي من البرد، اعمل كده بالصلاة والإنجيل والتناول.", "question": "إيه العادة اللي بتحفظك قريب من ربنا؟ وإيه اللي بيبعّدك؟", "reflectionReviewed": true}, "14": {"ref": "يو ١٦: ٣٣", "usfm": "JHN.16.33", "from": "LG", "text": "قَدْ كَلَّمْتُكُمْ بِهَذَا لِيَكُونَ لَكُمْ فِيَّ سَلَامٌ. فِي الْعَالَمِ سَيَكُونُ لَكُمْ ضِيقٌ، وَلَكِنْ ثِقُوا: أَنَا قَدْ غَلَبْتُ الْعَالَمَ.", "title": "ثقوا", "reflection": "المسيح ما وعدناش بحياة من غير ضيق. قالها صريحة: في العالم هيبقى ليكم ضيق. بس كمّل: ثقوا، أنا غلبت العالم. السلام اللي بيدّيه مش إن مفيش مشاكل. ده إنك فيه وعايش في حماه وسط المشاكل.", "question": "إيه الضيق اللي محتاج تسمع فيه كلمة «ثقوا» النهارده؟", "reflectionReviewed": true}, "15": {"ref": "لو ١٢: ٧", "usfm": "LUK.12.7", "from": "LG", "text": "بَلْ شُعُورُ رُؤُوسِكُمْ أَيْضًا جَمِيعُهَا مُحْصَاةٌ. فَلَا تَخَافُوا! أَنْتُمْ أَفْضَلُ مِنْ عَصَافِيرَ كَثِيرَةٍ!", "title": "معدودة", "reflection": "النهارده تذكار استشهاد مارمينا العجايبي. المسيح بيقول لتلاميذه ما يخافوش، لأن حتى شعر راسهم معدود عند ربنا. لو ربنا عارف التفاصيل الصغيرة دي، يبقى اكيد عارفك وبيحبك وشايلك.", "question": "إيه الخوف اللي بيرجعلك كتير؟ قول لربنا عليه.", "reflectionReviewed": true}, "16": {"ref": "لو ١٢: ٣٤", "usfm": "LUK.12.34", "from": "LG", "text": "لِأَنَّهُ حَيْثُ يَكُونُ كَنْزُكُمْ هُنَاكَ يَكُونُ قَلْبُكُمْ أَيْضًا.", "title": "فين كنزك؟", "reflection": "النهارده أول يوم في صوم الميلاد. والمسيح بيقول إن قلبك بيروح ورا الحاجة اللي إنت شايفها كنزك. الصوم فرصة نرتّب الكنوز دي: ربنا الأول، والباقي بعده.", "question": "إيه الحاجة اللي واخدة قلبك أكتر من اللازم، وممكن تصوم عنها شوية؟", "reflectionReviewed": true}, "17": {"ref": "مت ٥: ١٦", "usfm": "MAT.5.16", "from": "VG", "text": "فَلْيُضِئْ نُورُكُمْ هَكَذَا قُدَّامَ النَّاسِ، لِكَيْ يَرَوْا أَعْمَالَكُمُ الْحَسَنَةَ، وَيُمَجِّدُوا أَبَاكُمُ الَّذِي فِي السَّمَاوَاتِ.", "title": "فليضئ نوركم", "reflection": "النور مش للعرض. المسيح بيقول خلّي نورك يبان قدام الناس، بس الهدف إنهم يمجّدوا الآب، مش إنهم يمدحوك انت. الأعمال الحلوة الصغيرة بتتكلم عن ربنا أكتر من عظات كتير.", "question": "إيه عمل حلو صغير تقدر تعمله النهارده من غير ما تستنى شكر؟", "reflectionReviewed": true}, "18": {"ref": "مت ١٠: ٨", "usfm": "MAT.10.8", "from": "LG", "text": "اِشْفُوا مَرْضَى. طَهِّرُوا بُرْصًا. أَقِيمُوا مَوْتَى. أَخْرِجُوا شَيَاطِينَ. مَجَّانًا أَخَذْتُمْ، مَجَّانًا أَعْطُوا.", "title": "مجانًا أعطوا", "reflection": "المسيح بعت تلاميذه يخدموا، ووصّاهم: اللي خدتوه ببلاش، اِدّوه ببلاش. كل اللي عندنا هدية من ربنا: إيماننا، ومواهبنا، ووقتنا. والطبيعي إن الهدية دي تعدّي مننا لغيرنا.", "question": "إيه موهبة أو حاجة عندك ممكن تدّيها لحد النهارده من غير مقابل؟", "reflectionReviewed": true}, "19": {"ref": "مت ١٠: ٣٢", "usfm": "MAT.10.32", "from": "VG", "text": "فَكُلُّ مَنْ يَعْتَرِفُ بِي قُدَّامَ النَّاسِ أَعْتَرِفُ أَنَا أَيْضًا بِهِ قُدَّامَ أَبِي الَّذِي فِي السَّمَاوَاتِ.", "title": "يعترف بي", "reflection": "مش دايمًا سهل تقول قدام صحابك إنك بتصلّي وبتصوم وبتروح الكنيسة. المسيح بيقول اللي يعترف بيه قدام الناس، هو هيعترف بيه قدام الآب. والاعتراف ممكن يبقى في تصرف صغير، مش بس في كلام.", "question": "فيه موقف بتتكسف فيه تبيّن إيمانك؟", "reflectionReviewed": true}, "20": {"ref": "١ بط ٤: ١٠", "usfm": "1PE.4.10", "from": "CA", "text": "لِيَكُنْ كُلُّ وَاحِدٍ بِحَسَبِ مَا أَخَذَ مَوْهِبَةً، يَخْدِمُ بِهَا بَعْضُكُمْ بَعْضًا، كَوُكَلَاءَ صَالِحِينَ عَلَى نِعْمَةِ اللهِ الْمُتَنَوِّعَةِ.", "title": "موهبة للخدمة", "reflection": "كل واحد فينا أخد موهبة: صوت، أو رسم، أو تنظيم، أو ودن بتسمع اللي حواليها بمحبة. بطرس بيقول إننا وكلاء عليها، يعني مش ملكنا نخزّنها. دي أمانة نخدم بيها بعض.", "question": "إيه موهبتك؟ وإزاي تخدم بيها حد في الكنيسة أو في البيت؟", "reflectionReviewed": true}, "21": {"ref": "١ بط ٥: ٧", "usfm": "1PE.5.7", "from": "CA", "text": "مُلْقِينَ كُلَّ هَمِّكُمْ عَلَيْهِ، لِأَنَّهُ هُوَ يَعْتَنِي بِكُمْ.", "title": "ارمي همّك", "reflection": "النهارده تذكار السيدة العذراء. وبطرس بيقول ارموا كل همّكم على ربنا، لأنه بيهتم بيكم. مش جزء من الهم لا، كله! ربنا مش بيستحمل همّك وهو متضايق، ده بيهتم بيك فعلًا.", "question": "فكّر في ٣ حاجات شاغلاك، وقدّمهم لربنا في صلاة قصيرة.", "reflectionReviewed": true}, "22": {"ref": "مر ٨: ٣٤", "usfm": "MRK.8.34", "from": "MG", "text": "وَدَعَا الْجَمْعَ مَعَ تَلَامِيذِهِ وَقَالَ لَهُمْ: «مَنْ أَرَادَ أَنْ يَأْتِيَ وَرَائِي فَلْيُنْكِرْ نَفْسَهُ وَيَحْمِلْ صَلِيبَهُ وَيَتْبَعْنِي».", "title": "يحمل صليبه", "reflection": "اتّباع المسيح مش مجرد إعجاب بيه. هو بيقول: اللي عايز ييجي ورايا ينكر نفسه ويشيل صليبه. يعني يقدّم مشيئة ربنا على راحته، ويقبل التعب اللي بييجي مع الطريق ده.", "question": "إيه الحاجة الصغيرة اللي ممكن تنكر فيها نفسك النهارده عشان خاطر حد؟", "reflectionReviewed": true}, "23": {"ref": "يو ١٦: ٢٤", "usfm": "JHN.16.24", "from": "LG", "text": "إِلَى الْآنَ لَمْ تَطْلُبُوا شَيْئًا بِاسْمِي. اُطْلُبُوا تَأْخُذُوا، لِيَكُونَ فَرَحُكُمْ كَامِلًا.", "title": "اطلبوا", "reflection": "المسيح بيقول لتلاميذه: لحد دلوقتي ما طلبتوش حاجة باسمي. اطلبوا وهتاخدوا، وفرحكم يبقى كامل. ربنا عايزنا نكلّمه عن احتياجاتنا بثقة، زي ابن بيطلب من أبوه.", "question": "إيه الطلبة اللي نفسك فيها ومش بتقولها لربنا؟ قولها النهارده.", "reflectionReviewed": true}, "24": {"ref": "يو ١: ٥", "usfm": "JHN.1.5", "from": "LG", "text": "وَالنُّورُ يُضِيءُ فِي الظُّلْمَةِ، وَالظُّلْمَةُ لَمْ تُدْرِكْهُ.", "title": "النور يضيء", "reflection": "يوحنا بيبدأ إنجيله بإن المسيح هو الكلمة والنور. والنور ده بيضيء في الضلمة، والضلمة ما قدرتش تطفيه. مهما كانت الضلمة حواليك أو جواك، مش أقوى من نوره.", "question": "فين الضلمة اللي محتاج تدخّل فيها نور المسيح؟", "reflectionReviewed": true}, "25": {"ref": "٢ كو ١٠: ٤", "usfm": "2CO.10.4", "from": "PA", "text": "إِذْ أَسْلِحَةُ مُحَارَبَتِنَا لَيْسَتْ جَسَدِيَّةً، بَلْ قَادِرَةٌ بِاللهِ عَلَى هَدْمِ حُصُونٍ.", "title": "أسلحة مش جسدية", "reflection": "النهارده تذكار الشهيد أبي سيفين. وبولس بيقول إن حربنا مش بالسلاح العادي. أسلحتنا قوية بربنا: الصلاة، والإنجيل، والاتضاع. بيها بتقع الحصون اللي جوانا، زي الكبرياء والخوف.", "question": "إيه الحصن اللي جواك محتاج سلاح الصلاة عشان يقع؟", "reflectionReviewed": true}, "26": {"ref": "رو ٨: ١٥", "usfm": "ROM.8.15", "from": "PA", "text": "إِذْ لَمْ تَأْخُذُوا رُوحَ الْعُبُودِيَّةِ أَيْضًا لِلْخَوْفِ، بَلْ أَخَذْتُمْ رُوحَ التَّبَنِّي الَّذِي بِهِ نَصْرُخُ: «يَا أَبَا الْآبُ».", "title": "يا أبا الآب", "reflection": "بولس بيقول إحنا ما أخدناش روح عبودية نعيش بيها في خوف من ربنا. أخدنا روح البنوة، اللي بيها نقول لربنا: يا أبا، يعني يا أبويا. علاقتنا بيه علاقة ابن بأبوه، مش عبد بسيده.", "question": "إزاي بتكلّم ربنا في صلاتك: زي ابن، ولا زي حد خايف؟", "reflectionReviewed": true}, "27": {"ref": "مر ١٠: ٢٧", "usfm": "MRK.10.27", "from": "LG", "text": "فَنَظَرَ إِلَيْهِمْ يَسُوعُ وَقَالَ: «عِنْدَ النَّاسِ غَيْرُ مُسْتَطَاعٍ، وَلَكِنْ لَيْسَ عِنْدَ اللهِ، لِأَنَّ كُلَّ شَيْءٍ مُسْتَطَاعٌ عِنْدَ اللهِ».", "title": "كل شيء مستطاع", "reflection": "الشاب الغني مشي حزين لأنه ما قدرش يسيب فلوسه. والتلاميذ سألوا: أُمّال مين يقدر يخلص؟ والمسيح بصّلهم وقال: عند الناس مستحيل، بس عند ربنا كل حاجة ممكنة.", "question": "إيه الحاجة اللي شايفها مستحيلة في حياتك؟ سلّمها لربنا.", "reflectionReviewed": true}, "28": {"ref": "٣ يو ١: ٤", "usfm": "3JN.1.4", "from": "CA", "text": "لَيْسَ لِي فَرَحٌ أَعْظَمُ مِنْ هَذَا: أَنْ أَسْمَعَ عَنْ أَوْلَادِي أَنَّهُمْ يَسْلُكُونَ بِالْحَقِّ.", "title": "ماشيين في الحق", "reflection": "يوحنا الرسول كتب رسالة قصيرة لصاحبه غايس، وقاله إن أكبر فرحة عنده إنه يسمع إن أولاده ماشيين في الحق. الخادم بتاعك وأب اعترافك بيفرحوا بنفس الطريقة لما يشوفوك ماشي صح ناحية ربنا.", "question": "مين الشخص اللي بيفرح بيك روحيًا؟ ابعتله رسالة شكر النهارده.", "reflectionReviewed": true}, "29": {"ref": "عب ٤: ١٦", "usfm": "HEB.4.16", "from": "PA", "text": "فَلْنَتَقَدَّمْ بِثِقَةٍ إِلَى عَرْشِ النِّعْمَةِ لِكَيْ نَنَالَ رَحْمَةً وَنَجِدَ نِعْمَةً عَوْنًا فِي حِينِهِ.", "title": "بثقة", "reflection": "رسالة العبرانيين بتقول إن عندنا رئيس كهنة فاهم ضعفنا، هو المسيح. عشان كده نقدر نقرّب لعرش النعمة بثقة، مش بخوف، نطلب رحمة ونلاقي معونة في الوقت اللي محتاجينها فيه.", "question": "إيه اللي مخلّيك متردد تقرّب من ربنا؟", "reflectionReviewed": true}, "30": {"ref": "٢ كو ٤: ٧", "usfm": "2CO.4.7", "from": "PA", "text": "وَلَكِنْ لَنَا هَذَا الْكَنْزُ فِي أَوَانٍ خَزَفِيَّةٍ، لِيَكُونَ فَضْلُ الْقُوَّةِ لِلهِ لَا مِنَّا.", "title": "كنز في أواني خزف", "reflection": "إحنا زي أواني الفخار: بسيطة وبتنكسر بسهولة. وجوانا كنز غالي جدًا، هو نعمة ربنا. وده مقصود، عشان لما حاجة حلوة تحصل يبان إن القوة من ربنا مش مننا.", "question": "إيه ضعفك اللي ممكن ربنا يبيّن قوته من خلاله؟", "reflectionReviewed": true}}, "reflectionsReview": {"date": "2026-11-05", "by": "مراجع سراج", "file": "review/siou-hator-verses-review-approved.xlsx", "result": "٣٠ موافق، والتعديلات اتعملت في النص نفسه", "followups": ["٦: رجوع جملة «والأرض الجيدة بتعمل ٣ حاجات:»", "١٥: العنوان «معدودة»", "٢١: «كله!» من غير نقطة"]}, "year": 1743};
var SLOT_NAME = { LG: 'إنجيل القداس', PA: 'البولس', CA: 'الكاثوليكون', AC: 'الإبركسيس', VG: 'إنجيل العشية', MG: 'إنجيل باكر' };
// الفراغات في المرحلة الأولى: أطول ٤ كلمات مختلفة (٣ لو الآية قصيرة)، بترتيبها في الآية
function bare(w) { return w.replace(/[\u064B-\u0652\u0670]/g, '').replace(/[^\u0621-\u064A]/g, ''); }
function autoGaps(words) {
  var n = words.length < 9 ? 3 : 4, seen = {}, pick = [];
  words.map(function (w, i) { return { i: i, b: bare(w) }; })
    .sort(function (x, y) { return y.b.length - x.b.length || x.i - y.i; })
    .forEach(function (o) { if (pick.length < n && o.b.length > 2 && !seen[o.b]) { seen[o.b] = 1; pick.push(o.i); } });
  return pick.sort(function (x, y) { return x - y; });
}
var CONTENT = {};
Object.keys(VERSES.days).forEach(function (d) {
  var v = VERSES.days[d], words = v.text.split(' '), ok = !!v.reflectionReviewed;
  CONTENT[VERSES.year + '-' + VERSES.month + '-' + d] = {
    verse: { ref: v.ref, words: words, gaps: v.gaps || autoGaps(words) }, from: SLOT_NAME[v.from] || '',
    theme: ok ? v.title : null, reflection: ok ? v.reflection : null, question: ok ? v.question : null
  };
});
